local CatHouseCountdownNode = Class('CatHouseCountdownNode')

------------ import ------------
---@type CatHouseMgr
local CatHouseMgr = import('Game.CatHouse.CatHouseMgr')
local KTool = CS.Engine.Lib.KTool
------------ import ------------

------------ define ------------
local ConstantsCatHouse = CatHouseMgr.ConstantsCatHouse
local CatStatus = ConstantsCatHouse.CatStatus
local UICatStatus = ConstantsCatHouse.UICatStatus
local GetTimeHMS2 = CfUtils.GetTimeHMS2

local CatStatus2CDCatStatus = {
    [CatStatus.Signup] = UICatStatus.RallySignup,
    [CatStatus.Recovering] = UICatStatus.Recovering,
    [CatStatus.Waiting] = UICatStatus.Waiting,
    [CatStatus.Exploring] = UICatStatus.Exploring,
}

local CDCatStatusText = {
    [UICatStatus.RallySignup] = { localize("集会"), localize("集会结束") },
    [UICatStatus.Recovering] = { localize("恢复") },
    [UICatStatus.Waiting] = { localize("请求"), localize("请求失败") },
    [UICatStatus.Exploring] = { localize("探险"), localize("探险结束") },
}

------------ define ------------

function CatHouseCountdownNode:__init()
    self.catStatus = nil
end

function CatHouseCountdownNode:__delete()
    self.catStatus = nil
end

function CatHouseCountdownNode:Awake()

end

function CatHouseCountdownNode:OnDestroy()
    self:RemoveCDEvent()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end


