---FreshUI
function CatHouseCountdownNode:FreshUI(catData)
    ---如果是孵化的话只有一个id字段  id ->  deliveryList.deliveryId
    self.catId = tostring(catData.id)
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    self.cdData = component:GetCDDataById(self.catId)

    --- 有倒计时数据 并且 不是 （倒计时数据 只有一条 并且 是吃撑）warn: 吃撑只是模型上表现 UI上只会有弹窗提示
    local isShowStatus = false
    local uiCatStatus
    if self.cdData then
        for state, remainTime in pairs(self.cdData) do
            uiCatStatus = CatStatus2CDCatStatus[state]
            if uiCatStatus then
                self:FreshCd(remainTime, uiCatStatus)
                --- 恢复期没有完成状态
                if remainTime == 0 then
                    isShowStatus = uiCatStatus ~= UICatStatus.Recovering
                else
                    isShowStatus = remainTime > 0
                end
                if remainTime > 0 then
                    self:AddCDEvent()
                end
                break
            end
        end
    else
        self:RemoveCDEvent()
    end

    KTool.SetActive(self.controller.gameObject, isShowStatus)
end

function CatHouseCountdownNode:FreshCd(remainTime, cdCatStatus)
    local isOngoing = remainTime > 0
    local ongoingText, endingText = SafeUnpack(CDCatStatusText[cdCatStatus])
    local text = isOngoing and ongoingText or endingText
    local isShowText = text ~= nil

    KTool.SetActive(self.Underway.gameObject, isOngoing)
    KTool.SetActive(self.Complete.gameObject, not isOngoing)
    if isOngoing then
        self.TextTitle.text = text
        self.TextNumber.text = GetTimeHMS2(remainTime)
    elseif isShowText then
        self.CompleteTextTitle.text = text
    end

end

function CatHouseCountdownNode:AddCDEvent()
    if self.__EventTimeChangeAction then
        return
    end
    self.__EventTimeChangeAction = Events.AddListener(Constants.EventNames.CatHouseTimeChange, Bind(self, self.OnEventTimeChangeAction))
end

function CatHouseCountdownNode:RemoveCDEvent()
    if self.__EventTimeChangeAction then
        Events.RemoveListener(Constants.EventNames.CatHouseTimeChange, self.__EventTimeChangeAction)
        self.__EventTimeChangeAction = nil
    end
end


