function CatHouseCountdownNode:OnEventTimeChangeAction()
    local cdData = self.cdData
    if cdData == nil then
        return
    end
    local cdCatStatus
    local seconds = 0
    for state, remainTime in pairs(cdData) do
        cdCatStatus = CatStatus2CDCatStatus[state]
        if cdCatStatus then
            seconds = remainTime
            break
        end
    end

    local isTimeEnd = seconds == 0
    if isTimeEnd then
        self:RemoveCDEvent()
    end

    if cdCatStatus == nil or (isTimeEnd and cdCatStatus == UICatStatus.Recovering) then
        KTool.SetActive(self.controller.gameObject, false)
    else
        self:FreshCd(seconds, cdCatStatus)
    end
end
---------------------------------------------------
--- handler end --
